LITERAL = re.compile(r'"((?:[^"\\\n]|\\.)*)"')
SQL = re.compile(r'\b(?:SELECT|INSERT|UPDATE|DELETE|MERGE|BEGIN|DECLARE|FROM|WHERE)\b')


class CalendarServiceLinesTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp = tempfile.TemporaryDirectory()
        root = Path(cls.temp.name)
        (root / 'naptar_fmb.xml').write_text(FORM, encoding='utf-8')
        (root / 'config.json').write_text(json.dumps({'backend_live': True}), encoding='utf-8')
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            assert main(['migrate', str(root / 'naptar_fmb.xml'), '--screen', '--module', 'naptar',
                         '--config', str(root / 'config.json'), '--out', str(root / 'out')]) == 0
        cls.out = root / 'out'

    @classmethod
    def tearDownClass(cls):
        cls.temp.cleanup()

    def test_headstart_calendar_block_and_window_are_not_generated(self):
        screen = json.loads((self.out / 'analysis/screen-plan.json').read_text(encoding='utf-8'))
        self.assertIn('CALENDAR', [b['block'] for b in screen['framework_blocks']])
        calendar = [w for w in screen['windows'] if w['name'] == 'CALENDAR']
        self.assertTrue(all(not w['canvases'] for w in calendar))  # recorded as empty, never rendered
        component = (self.out / 'frontend/naptar/naptar.component.ts').read_text(encoding='utf-8')
        self.assertNotIn('CALENDAR', component)
        self.assertIsNone(re.search(r'cell\d', component, re.I))
        plan = json.loads((self.out / 'analysis/backend-plan.json').read_text(encoding='utf-8'))
        self.assertFalse([e for e in plan['endpoints'] if str(e.get('owner', '')).startswith('CALENDAR.')])

    def test_services_are_plain_spring_services(self):
        for layer in ('DPS', 'WBS'):
            service = (self.out / 'backend' / layer / 'NaptarServiceImpl.java').read_text(encoding='utf-8')
            self.assertIn('\n@Service\n', service)
            self.assertNotIn('@Service(', service)

    def test_no_sql_literal_line_reaches_120_characters(self):
        checked = 0
        for path in (self.out / 'backend').rglob('*.java'):
            for line in path.read_text(encoding='utf-8').split('\n'):
                if not line.lstrip().startswith('//') and any(SQL.search(m.group(1)) for m in LITERAL.finditer(line)):
                    checked += 1
                    self.assertLess(len(line), 120, path.name + ': ' + line)
        self.assertGreater(checked, 0)

    def test_wrapping_keeps_the_exact_string_value(self):
        source = ('class X {\n        int count = jdbc.update("DELETE FROM ANK_ADLAP_ITEMS_NAGYON_HOSSZU_TABLANEV WHERE AIT_KULCS = '
                  ':aitKulcs AND \\"MEZO\\" = \\u00e9", paramsAit(row));\n}\n')
        wrapped = wrap_strings(source)
        self.assertTrue(all(len(line) < 120 for line in wrapped.split('\n')))
        self.assertEqual(''.join(LITERAL.findall(source)), ''.join(LITERAL.findall(wrapped)))
        self.assertGreater(wrapped.count('\n'), source.count('\n'))


if __name__ == '__main__':
    unittest.main()
